def tail(d,detail):
    return group('tail','tail',path(d,f'url(#{prefix}-fur)','#705035',3)+path(detail,'none','#e6b972',6))
def body(d,chest,details=''):
    return group('body','body',path(d,f'url(#{prefix}-fur)','#705035',3.1)+path(chest,f'url(#{prefix}-face)','#c8965a',1.7)+path(details,'none','#a1703e',2) if details else path(d,f'url(#{prefix}-fur)','#705035',3.1)+path(chest,f'url(#{prefix}-face)','#c8965a',1.7))
def limb(id,d,hand,detail=''):
    return group(id,'arm' if 'arm' in id else 'leg',path(d,f'url(#{prefix}-fur)','#705035',3)+path(hand,'#67503b','#4a4033',2.7)+path(detail,'none','#9c7854',1.8))
